/bin/bash -lc "PYTHONDONTWRITEBYTECODE=1 python check.py
PYTHONDONTWRITEBYTECODE=1 python - <<'PY'
from service import offset

for page in (1, 2, 4, 100, 10**20):
    for size in range(1, 101):
        assert offset(page, size) == (page - 1) * size

for page in (0, -1, 1.0, 1.5, True, False, None, '1'):
    try:
        offset(page, 10)
    except ValueError:
        pass
    else:
        raise AssertionError(('page', page))

for size in (0, -1, 101, 1.0, 1.5, True, False, None, '10'):
    try:
        offset(1, size)
    except ValueError:
        pass
    else:
        raise AssertionError(('size', size))

print('Pagination boundary and invalid-input checks passed.')
PY"

